package com.vibecode.roadmap.web;
import com.vibecode.output.domain.*; import com.vibecode.prompt.application.DeterministicPromptBuilder; import com.vibecode.prompt.domain.*; import com.vibecode.roadmap.application.*; import com.vibecode.roadmap.domain.*; import com.vibecode.task.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/projects/{projectId}") public class WorkflowController {private final WorkflowService flow;private final ProjectStateService state;private final DeterministicNextStepEngine next;private final DeterministicPromptBuilder prompts;public WorkflowController(WorkflowService f,ProjectStateService s,DeterministicNextStepEngine n,DeterministicPromptBuilder p){flow=f;state=s;next=n;prompts=p;}
 @PostMapping("/roadmap") ResponseEntity<RoadmapRecord> roadmap(@PathVariable UUID projectId){return ResponseEntity.status(HttpStatus.CREATED).body(flow.createRoadmap(projectId));}@GetMapping("/roadmap") Object roadmapGet(@PathVariable UUID projectId){return flow.roadmap(projectId).map(r->Map.of("id",r.id(),"phases",flow.phases(projectId))).orElse(Map.of("phases",List.of()));}@PostMapping("/roadmap/phases") ResponseEntity<RoadmapPhaseRecord> phase(@PathVariable UUID projectId,@Valid @RequestBody PhaseRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(flow.addPhase(projectId,r.position(),r.title(),r.description()));}@PostMapping("/roadmap/phases/{phaseId}/tasks") ResponseEntity<WorkflowTask> task(@PathVariable UUID projectId,@PathVariable UUID phaseId,@Valid @RequestBody TaskRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(flow.addTask(projectId,phaseId,r.position(),r.title(),r.objective(),r.riskLevel()));}@PostMapping("/tasks/{taskId}/dependencies") ResponseEntity<Void> dep(@PathVariable UUID projectId,@PathVariable UUID taskId,@Valid @RequestBody DependencyRequest r){flow.dependency(projectId,taskId,r.dependsOnTaskId());return ResponseEntity.noContent().build();}@PostMapping("/tasks/{taskId}/criteria") ResponseEntity<TaskAcceptanceCriterionRecord> criterion(@PathVariable UUID projectId,@PathVariable UUID taskId,@Valid @RequestBody CriterionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(flow.criterion(projectId,taskId,r.description(),r.required()));}
 @GetMapping("/state") ProjectState state(@PathVariable UUID projectId){return state.state(projectId);}@GetMapping("/next-step") WorkflowRecommendation next(@PathVariable UUID projectId){return next.recommend(projectId);}@PostMapping("/tasks/{taskId}/evidence") ResponseEntity<OutputAnalysisRecord> evidence(@PathVariable UUID projectId,@PathVariable UUID taskId,@Valid @RequestBody EvidenceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(flow.addEvidence(projectId,taskId,r.type(),r.rawContent(),r.source()));}@GetMapping("/tasks/{taskId}/evidence") List<TaskEvidence> evidenceGet(@PathVariable UUID projectId,@PathVariable UUID taskId){return flow.evidence(projectId,taskId);}@PostMapping("/prompts/generate") GeneratedPrompt prompt(@PathVariable UUID projectId,@Valid @RequestBody PromptGenerateRequest r){return prompts.generate(projectId,r.taskId(),r.type());}
 public record PhaseRequest(@Min(1) int position,@NotBlank @Size(max=160) String title,@Size(max=5000) String description){} public record TaskRequest(@Min(1) int position,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=10000) String objective,@NotNull RiskLevel riskLevel){} public record DependencyRequest(@NotNull UUID dependsOnTaskId){} public record CriterionRequest(@NotBlank @Size(max=5000) String description,boolean required){} public record EvidenceRequest(@NotNull EvidenceType type,@NotBlank @Size(max=200000) String rawContent,@NotBlank @Size(max=80) String source){} public record PromptGenerateRequest(UUID taskId,@NotNull PromptType type){}
}
